var t=ST.fmt(ST.pick(S,ITH_SIGN),{a:I.v.name,b:b?b.name:'仲間'});
if(!sh||rng()>ch){ST.say(S,{actors:b?[b]:[],tag:'違和感',text:t,why:'……'+I.v.name+'の様子がおかしい',mag:18});return true;}
reveal(S,sh,vs,t);
