S.x=tr0?tr0.x:mot.triangle?rng.pick(pool.filter(function(q){return q!==v1;}))||S.acc:mot.id==='mistake'?rng.pick(pool.filter(function(q){return q!==v1;}).concat(S.host.npc?[S.host]:[])):S.acc;
