if(day===1)murder(S,S.v1,day,true);
else if(day<=env.days&& !(Y.R18&&Y.R18.on(S)&&(Y.R18.night(S,day)||(Y.R18.extra&&Y.R18.extra(S,day)))))nightMurder(S,day);
ST.flushShort(S,'ほかに：');
if(S.over)break;
if(day>env.days)break;
