if(SH.X2&&SH.X2.AFTER)Object.keys(SH.X2.AFTER).forEach(function(k){SH.X2.AFTER[k]=markAfter(SH.X2.AFTER[k]);});
if(SH.X&&SH.X.lureAfter)SH.X.lureAfter=markAfter(SH.X.lureAfter);
