a.inf=1;a.infSrc=src;stress(a,10);a.cnt.inf=(a.cnt.inf||0)+1;
ST.say(S,{actors:[a],tag:'感染症',text:F(pk(S,SH.C.INF_START),{a:a.name,x:src}),why:src+'の調査で、未知の病原体に感染した',mag:26});
if(SH.AFTER)SH.AFTER.react(S,a,'start');
