a.away='lost';a.awayM=0;stress(a,15);
var o=ST.say(S,{actors:[a],tag:'遭難',text:F(pk(S,SH.C.LOST),{a:a.name}),why:'探索の失敗で、仲間とはぐれた',mag:30});
ST.key(S,o,a.name+'の遭難');
