if(a.awayM>=3){a.gone=true;a.fate='遭難して行方不明（'+S.m+'か月目）';ST.say(S,{actors:[a],tag:'行方不明',text:F(pk(S,C.LOST_GONE),{a:a.name}),why:'三か月探しても見つからなかった',mag:30});}
