ST.say(S,{actors:[a,b],tag:'看病の夜',kind:'climax',text:open+body+F(pk(S,R.nurseAfter),{a:a.name,b:b.name}),why:'熱に浮かされた'+b.name+'と、看病していた'+a.name+'／関係の近さ '+Math.round(bond(S,a,b)*100),mag:30});
