if(seer&&rankW[0]&&fakeScore(rankW[0])>0.62+rng()*0.2){plan.fake=rankW[0];plan.tags.push('fake');}
if(med&&rankW[1]&&fakeScore(rankW[1])>0.66+rng()*0.15){plan.fakeMed=rankW[1];plan.tags.push('fakeMed');}
